{"summary": "Add New Property Listing", "description": "Add a new property listing to the service with details like location, price, type, and description.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/PropertyCreate"}}}}, "responses": {"201": {"description": "Property listing created successfully.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}}}

Endpoint: POST /rate-sensitivity-analysis
Specification:
{"summary": "Simulate Interest Rate Changes", "description": "Simulate changes in interest rates to understand their impact on loan terms and payments.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"loanAmount": {"type": "number", "description": "The loan amount in USD."}, "currentInterestRate": {"type": "number", "description": "The current interest rate as a percentage."}, "rateScenarios": {"type": "array", "description": "Array of interest rate scenarios to simulate.", "items": {"type": "object", "properties": {"rate": {"type": "number", "description": "The interest rate to simulate as a percentage."}}}}}, "required": ["loanAmount", "currentInterestRate", "rateScenarios"]}}}}, "responses": {"200": {"description": "Rate sensitivity analysis completed successfully.", "content": {"application/json": {"schema": {"type": "array", "description": "Sensitivity analysis for each interest rate scenario.", "items": {"type": "object", "properties": {"interestRate": {"type": "number", "description": "The simulated interest rate."}, "monthlyPayment": {"type": "number", "description": "The monthly payment amount under this rate."}, "totalInterest": {"type": "number", "description": "The total interest over the loan tenure."}}}}}}}}}

Endpoint: GET /properties
Specification:
{"summary": "Fetch Properties", "description": "Retrieve the list of available properties for sale or rent.", "responses": {"200": {"description": "List of available properties.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Property"}}}}}}}

Endpoint: POST /tenant/register
Specification:
{"summary": "Register a new tenant", "description": "Add a tenant to the system for a specific property.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"tenantId": {"type": "string", "description": "Unique identifier for the tenant."}, "propertyId": {"type": "string", "description": "Unique identifier for the property."}, "name": {"type": "string", "description": "Name of the tenant."}, "email": {"type": "string", "description": "Email address of the tenant."}}, "required": ["tenantId", "propertyId", "name", "email"]}}}}, "responses": {"201": {"description": "Tenant registered successfully."}, "400": {"description": "Invalid request payload."}}}

Endpoint: POST /search-saved
Specification:
{"summary": "Save new search criteria", "description": "Allow users to save new search configurations for later use.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/SavedSearchInput"}}}}, "responses": {"201": {"description": "New search configuration saved successfully.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/SavedSearch"}}}}}}

Endpoint: GET /interest-rates
Specification:
{"summary": "Get Interest Rates", "description": "Retrieve current and historical interest rates for mortgage loans to aid comparison and decision-making.", "responses": {"200": {"description": "Interest rates data retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"currentInterestRate": {"type": "number", "description": "The current interest rate as a percentage."}, "historicalRates": {"type": "array", "description": "An array of historical interest rates with their respective dates.", "items": {"type": "object", "properties": {"date": {"type": "string", "format": "date", "description": "The date of the historical interest rate."}, "rate": {"type": "number", "description": "The interest rate on the specified date."}}}}}}}}}}}

Endpoint: GET /properties/featured
Specification:
{"summary": "Retrieve featured properties", "description": "Fetch a list of properties that are marked as featured or promoted by the platform.", "responses": {"200": {"description": "A list of featured properties.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Property"}}}}}}}

Endpoint: GET /vendors/list
Specification:
{"summary": "Retrieve approved vendors", "description": "Get a list of approved vendors available for maintenance services.", "responses": {"200": {"description": "Vendors retrieved successfully.", "content": {"application/json": {"schema": {"type": "array", "items": {"type": "object", "properties": {"vendorId": {"type": "string", "description": "Unique identifier for the vendor."}, "name": {"type": "string", "description": "Name of the vendor."}, "contact": {"type": "string", "description": "Contact information for the vendor."}}}}}}}}}

Endpoint: POST /feedback
Specification:
{"summary": "Submit Service Feedback", "description": "Submit user feedback regarding the overall service.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Feedback"}}}}, "responses": {"201": {"description": "Feedback submitted successfully."}}}
